import{_ as a,o as e,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"Ceph Crimson/SeaStore 2021-08-11","description":"","frontmatter":{"title":"Ceph Crimson/SeaStore 2021-08-11","date":"2021-08-11T00:00:00.000Z","updated":"2021-08-21T00:00:00.000Z","tags":["Ceph","distributed storage","CI/CD","performance testing","software development"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Crimson_SeaStore_2021-08-11.md","filePath":"posts/2021/Ceph_Crimson_SeaStore_2021-08-11.md","lastUpdated":1780460162000}'),o={name:"posts/2021/Ceph_Crimson_SeaStore_2021-08-11.md"};function r(n,l,s,d,p,h){return e(),i("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="主要议题与讨论内容" tabindex="-1">主要议题与讨论内容 <a class="header-anchor" href="#主要议题与讨论内容" aria-label="Permalink to &quot;主要议题与讨论内容&quot;">​</a></h4><ol><li><p><strong>编译器替换</strong></p><ul><li>讨论将GCC编译器替换为Clang以解决Sealant构建失败的问题。</li><li>决定未来将使用Clang进行构建，并假设Clang通过的构建也能通过GCC。</li></ul></li><li><p><strong>FIO构建问题</strong></p><ul><li>解决FIO在Clang 10或Sealant 11上构建失败的问题，创建了PR来移除头文件中的<code>namespace lcd_one</code>声明。</li><li>对FIO本身的问题创建了补丁，使用原子操作库实现顺序锁。</li></ul></li><li><p><strong>测试与调试</strong></p><ul><li>解决FIO测试在没有调试信息输出时容易失败的问题。</li><li>讨论了回归问题，可能由最近的集成引入，需要进一步调查。</li></ul></li><li><p><strong>开发进展</strong></p><ul><li>讨论scrubbing相关问题，正在处理并计划添加新的PR。</li><li>提到LBA管理器的重写已通过单元测试，正在进行集成工作。</li><li>讨论多设备支持的进展，几乎完成，但仍在调试中。</li></ul></li><li><p><strong>性能与冲突分析</strong></p><ul><li>讨论从旧节点到LBA的冲突移动，通过图表比较了集成前后的情况。</li><li>考虑在CI中集成性能测试工具的可能性，但目前不是优先事项。</li></ul></li><li><p><strong>编译问题与CI/CD</strong></p><ul><li>通过启用CCache改善编译速度问题。</li><li>讨论CI/CD系统升级和相关问题，包括网络配置和包管理。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>未来使用Clang进行构建。</li><li>继续解决FIO构建问题，并优化测试流程。</li><li>推进多设备支持和LBA管理器的开发。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续解决FIO构建问题，并优化测试流程。</li><li>完成LBA管理器的集成工作，并准备提交PR。</li><li>继续调试多设备支持，并准备提交PR。</li><li>进一步分析和优化性能测试，考虑在CI中集成相关工具。</li><li>解决CI/CD系统升级中的问题，并优化构建流程。</li></ul><h4 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h4><ul><li>讨论了具体的编译命令和测试案例，以及如何处理Jenkins任务的取消。</li><li>讨论了如何处理特定的编译和集成问题，包括回归问题和代码修改。</li></ul><h3 id="结束语" tabindex="-1">结束语 <a class="header-anchor" href="#结束语" aria-label="Permalink to &quot;结束语&quot;">​</a></h3><p>会议结束时，所有参与者都表示将继续推进各自的工作，并保持沟通以解决遇到的问题。感谢所有人的参与和贡献，期待下次会议的进一步更新。</p>',11)])])}const _=a(o,[["render",r]]);export{C as __pageData,_ as default};
